          pSpawnXY = 0;
          nSpawnUnitSizeX = D2Common::Units::GetUnitSizeX(pUnit_00);
          pCorpseRoom = D2Common::DUNGEON::Dungeon::SpawnUnit(pGameOrig->pAct[bActNo], eLevelId, 0, (int*)&pDrlgAct, (int*)&pSpawnXY, nSpawnUnitSizeX);
